// Map the agent's structured data collection onto a small canonical outcome vocabulary.
const cfg = $('Load config').first().json;
const { event, campaign_key, run_name } = $('Start').first().json;
const c = cfg.campaigns[campaign_key];
const keys = { ...cfg.defaults.outcome_keys, ...(c.outcome_keys ?? {}) };
const aliases = { ...cfg.defaults.outcome_aliases, ...(c.outcome_aliases ?? {}) };
const d = event.data ?? {};
const dc = d.analysis?.data_collection_results ?? {};
const dv = d.conversation_initiation_client_data?.dynamic_variables ?? {};
const val = k => dc[k]?.value ?? null;
const why = k => dc[k]?.rationale ?? '';

if (!dv.contact_id) throw new Error(`Conversation ${d.conversation_id} has no contact_id — cannot reconcile to CRM`);

let raw = String(val(keys.outcome) ?? '').trim().toLowerCase().replace(/[\s-]+/g, '_');
if (!raw) raw = /voicemail/i.test(d.metadata?.termination_reason ?? '') ? 'voicemail' : 'failed';
const outcome = aliases[raw] ?? raw;

return [{ json: {
  campaign_key, run_name, campaign: c,
  contact: { id: dv.contact_id, name: dv.contact_name, email: dv.contact_email, phone: dv.contact_phone },
  outcome,
  requested_slot: val(keys.scheduled_datetime),
  reasons: { outcome: why(keys.outcome), refusal: why(keys.refusal_reason) },
  conversation_id: d.conversation_id,
  started_at: d.metadata?.start_time_unix_secs
    ? DateTime.fromSeconds(d.metadata.start_time_unix_secs).toUTC().toISO({ suppressMilliseconds: true })
    : DateTime.now().toUTC().toISO({ suppressMilliseconds: true }),
  duration_secs: d.metadata?.call_duration_secs ?? 0,
  wants_booking: outcome === 'booked' && c.booking?.enabled === true,
} }];

const n = $input.first().json;
if (!n.wants_booking) return [{ json: { op: 'noop' } }];
// The agent says a local wall-clock time; convert it in the campaign's timezone.
const start = DateTime.fromISO(String(n.requested_slot ?? ''), { zone: n.campaign.timezone });
if (!start.isValid) return [{ json: { op: 'noop', invalid_slot: true } }];
return [{ json: {
  op: 'book',
  event_type_uri: n.campaign.booking.event_type_uri,
  start_time: start.toUTC().toISO({ suppressMilliseconds: true }),
  invitee: { name: n.contact.name, email: n.contact.email, phone: n.contact.phone, timezone: n.campaign.timezone },
  tracking: { campaign: n.campaign_key },
} }];

const cfg = $('Load config').first().json;
const n = $('Normalize outcome').first().json;
const req = $('Calendar request').first().json;
const cal = $input.first().json;
const labels = { ...cfg.defaults.outcome_labels, ...(n.campaign.outcome_labels ?? {}) };

let outcome = n.outcome;
let summary;
if (n.wants_booking) {
  outcome = cal.ok ? 'booked' : 'booking_failed';
  summary = cal.ok
    ? `Booked for ${n.requested_slot} (${n.campaign.timezone})`
    : req.invalid_slot
      ? `Agent recorded a booking but the slot "${n.requested_slot}" is not a valid date-time`
      : `Agent agreed ${n.requested_slot} but the calendar rejected it: ${cal.error}`;
} else if (outcome === 'refused') {
  summary = n.reasons.refusal || n.reasons.outcome;
} else {
  summary = [n.reasons.outcome, n.reasons.refusal].filter(Boolean).join('\n\n');
}
const label = labels[outcome] ?? outcome.replace(/_/g, ' ').replace(/^./, s => s.toUpperCase());
const recording = cfg.voice.conversation_url_template.replace('{conversation_id}', n.conversation_id);

return [{ json: { op: 'log_activity', payload: {
  contact_id: n.contact.id, campaign_key: n.campaign_key, run_name: n.run_name,
  outcome_label: label, summary, started_at: n.started_at, duration_secs: n.duration_secs,
  conversation_id: n.conversation_id,
  note: `AI call outcome: ${label}\n\nSummary: ${summary || '—'}\n\nRecording: ${recording}`,
} } }];

const r = $input.first().json;
if (!r.ok) throw new Error(`CRM write failed (${r.status_code}): ${r.error}`);   // → error notifier
return [{ json: { logged: true, activity_id: r.id } }];
